import type { App, Screen } from '../app';
import { h } from '../dom';

/**
 * Port of guide_screen.gd. Shows public/guide.html (generated by
 * tools/build_guide.py and cached for offline use) inside the app.
 */
export function createGuideScreen(app: App): Screen {
  const body = h('div', { class: 'guide-body', 'aria-busy': 'true' }, h('p', { class: 'muted' }, 'Opening the guide…'));
  const element = h(
    'div',
    { class: 'screen guide', 'data-screen': 'guide' },
    h('header', { class: 'page-head' }, h('h1', {}, 'Artwork & custom decks'), h('button', { type: 'button', onclick: () => app.showSetup() }, 'Return to setup')),
    h('main', { class: 'guide-main' }, body),
    h(
      'footer',
      { class: 'guide-actions' },
      h('a', { class: 'button-link', href: 'guide.html', target: '_blank', rel: 'noopener' }, 'Open printable guide'),
      h('button', { type: 'button', onclick: () => app.showLibrary() }, 'Go to deck library'),
    ),
  );

  void fetch('guide.html')
    .then((response) => {
      if (!response.ok) throw new Error(String(response.status));
      return response.text();
    })
    .then((text) => {
      const page = new DOMParser().parseFromString(text, 'text/html');
      const sections = [...page.querySelectorAll('main > section')];
      const intro = page.querySelector('main > header p');
      // The guide is the app's own static page; its sections hold headings and text only.
      body.replaceChildren(...(intro ? [h('p', { class: 'guide-intro' }, intro.textContent ?? '')] : []), ...sections.map((section) => document.importNode(section, true)));
    })
    .catch(() => body.replaceChildren(h('p', {}, 'The guide could not be opened. Connect to the internet once so it can be saved for offline use.')))
    .finally(() => body.removeAttribute('aria-busy'));

  return { element, title: 'Adult guide' };
}
